# Verify and compute the requested U+V where U/V is the exact probability
from fractions import Fraction
import math
# Basic validation
for k in ['n','total_cubes','count_a','count_b','pattern_a','pattern_b','pattern_a_text','pattern_b_text']:
    if k not in assign:
        # Missing slot
        return (False, None)
n = assign['n']
N = assign['total_cubes']
count_a = assign['count_a']
count_b = assign['count_b']
pat_a = assign['pattern_a']
pat_b = assign['pattern_b']
# Domain checks
if not (isinstance(n, int) and n >= 3):
    # n must be at least 3
    return (False, None)
if N != n**3:
    return (False, None)
if not (isinstance(count_a, int) and isinstance(count_b, int)):
    return (False, None)
if count_a + count_b != N:
    return (False, None)
if count_a <= 0 or count_b <= 0:
    # Both types must appear
    return (False, None)
valid_patterns = {'2adj','2opp','3corner'}
if pat_a not in valid_patterns or pat_b not in valid_patterns:
    return (False, None)
# Surface class counts
C = 8
E = 12*(n-2)
F = 6*(n-2)**2
I = N - (C+E+F)
if E < 0 or F < 0 or I < 0:
    return (False, None)
# Map patterns to feature counts (# painted faces, # painted edge-adjacent pairs, # painted corners)
def feature_counts(code):
    if code == '2adj':
        return 4, 5, 2
    if code == '2opp':
        return 4, 4, 0
    if code == '3corner':
        return 3, 3, 1
    raise ValueError('invalid pattern')
pf_a, pe_a, pc_a = feature_counts(pat_a)
pf_b, pe_b, pc_b = feature_counts(pat_b)
# Probabilities for a randomly oriented cube of each type to satisfy class requirements
pA_C = Fraction(pc_a, 8)
pA_E = Fraction(pe_a, 12)
pA_F = Fraction(pf_a, 6)
pB_C = Fraction(pc_b, 8)
pB_E = Fraction(pe_b, 12)
pB_F = Fraction(pf_b, 6)
# Enforce non-triviality and non-zero probability: corners must be fillable
# If neither type has corner capacity, prob is zero -> invalid assignment for difficulty
if pc_a == 0 and pc_b == 0:
    return (False, None)
# If some corners must be type B but type B has no corner capacity, probability is zero.
# Ensure probability can be non-zero by requiring enough type A to cover all corners when type B corner capacity is zero.
if pc_b == 0 and count_a < C:
    return (False, None)
# Now compute the exact probability via multivariate hypergeometric over type placements and independent orientation success
total_choose = math.comb(N, count_a)
prob = Fraction(0, 1)
# Loop over possible allocations of type-A cubes to corners, edges, faces; interiors follow
xC_min = max(0, C - count_b)
xC_max = min(C, count_a)
for xC in range(xC_min, xC_max + 1):
    # Number of type-A cubes left for edges and faces and interior
    # xE range is 0..E but we constrain using interior capacity
    xE_min = 0
    xE_max = min(E, count_a - xC)
    for xE in range(xE_min, xE_max + 1):
        # xF must satisfy 0 <= xF <= F and 0 <= xI <= I where xI = count_a - xC - xE - xF
        lowF = max(0, count_a - xC - xE - I)
        highF = min(F, count_a - xC - xE)
        if lowF > highF:
            continue
        for xF in range(lowF, highF + 1):
            xI = count_a - xC - xE - xF
            # Check bounds
            if not (0 <= xI <= I):
                continue
            # Combinatorial probability of this type-A placement across classes
            ways = math.comb(C, xC) * math.comb(E, xE) * math.comb(F, xF) * math.comb(I, xI)
            placement_prob = Fraction(ways, total_choose)
            # Orientation success probability: product over classes
            orient = (pA_C ** xC) * (pB_C ** (C - xC)) * (pA_E ** xE) * (pB_E ** (E - xE)) * (pA_F ** xF) * (pB_F ** (F - xF))
            prob += placement_prob * orient
# Reduce and return U+V
prob = Fraction(prob.numerator, prob.denominator)  # already reduced
ans = prob.numerator + prob.denominator
return (True, ans)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

